-- ============================================================
-- spell_proc: Wailing Souls triggers off Searing Pain
-- ============================================================
-- SpellFamilyMask0 256 = Searing Pain (verified: gen_sql.py classmask
--   --family 5 --spells 5676)
-- ProcFlags 65536 = PROC_FLAG_DONE_SPELL_MAGIC_DMG_CLASS_NEG
-- SpellPhaseMask 2 = PROC_SPELL_PHASE_HIT  (MUST be non-zero)
-- NOTE: DELETE matches on ABS(SpellId).  A NEGATIVE spell_proc id means
-- "apply to the whole rank chain", and such a row is loaded first and
-- propagates to every rank -- any positive per-rank row for a later rank is
-- then rejected as a "duplicate entry" and silently discarded
-- (SpellMgr.cpp:2071).  The core ships negative rows for several of these
-- talents, so deleting only the positive ids would leave the core row in
-- charge with ProcFlags = 0 and the proc would never fire.
DELETE FROM `spell_proc` WHERE ABS(`SpellId`) IN (30299, 30301, 30302);
